import sys

def can_rearrange(words):
    if not words:
        return False

    # map letters a-z to indices 0-25
    indeg = [0] * 26
    outdeg = [0] * 26
    present = [False] * 26
    adj = [[] for _ in range(26)]

    for w in words:
        if not w:
            continue
        w_low = w.lower()
        start = ord(w_low[0]) - 97
        end = ord(w_low[-1]) - 97
        outdeg[start] += 1
        indeg[end] += 1
        present[start] = present[end] = True
        adj[start].append(end)
        adj[end].append(start)   # undirected for connectivity

    # check degree condition for Eulerian path/circuit
    start_nodes = end_nodes = 0
    for i in range(26):
        diff = outdeg[i] - indeg[i]
        if diff == 1:
            start_nodes += 1
        elif diff == -1:
            end_nodes += 1
        elif diff != 0:
            return False

    if not ((start_nodes == 1 and end_nodes == 1) or (start_nodes == 0 and end_nodes == 0)):
        return False

    # connectivity: all vertices with non‑zero degree must belong to one component
    # find a vertex with degree >0
    start_v = None
    for i in range(26):
        if outdeg[i] + indeg[i] > 0:
            start_v = i
            break
    if start_v is None:
        return False

    stack = [start_v]
    visited = [False] * 26
    visited[start_v] = True
    while stack:
        v = stack.pop()
        for nb in adj[v]:
            if not visited[nb]:
                visited[nb] = True
                stack.append(nb)

    for i in range(26):
        if (outdeg[i] + indeg[i] > 0) and not visited[i]:
            return False

    return True

def main():
    data = sys.stdin.read().strip()
    words = data.split()
    result = 1 if can_rearrange(words) else -1
    sys.stdout.write(str(result))

if __name__ == "__main__":
    main()
